import{_ as a,c as o,o as t,ax as s}from"./chunks/framework.DHqKNX4U.js";const p=JSON.parse('{"title":"Seat Counting","description":"","frontmatter":{},"headers":[],"relativePath":"enterprise/seats/guide.md","filePath":"enterprise/seats/guide.md"}'),n={name:"enterprise/seats/guide.md"};function r(i,e,d,l,c,h){return t(),o("div",null,e[0]||(e[0]=[s('<h1 id="seat-counting" tabindex="-1">Seat Counting <a class="header-anchor" href="#seat-counting" aria-label="Permalink to &quot;Seat Counting&quot;">​</a></h1><p>Open Archiver Enterprise is licensed per seat. A seat is one person whose emails are archived. This page explains how Open Archiver calculates the number of seats, which settings administrators can change, and what information is sent to the license server.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Open Archiver counts people, not mailboxes. Two adjustments make the seat count lower than the number of archived mailboxes:</p><ul><li>Shared mailboxes, role addresses such as <code>info@</code>, meeting rooms and equipment are not counted.</li><li>Several addresses that belong to the same person are counted as one seat.</li></ul><p>The <strong>Seats</strong> page is also available in the Open Source Edition, so you can see how many seats an Enterprise license would need before you buy one. The figure is calculated from the mailboxes already in your archive. On the Open Source Edition, nothing is reported to Open Archiver and nothing is enforced.</p><h2 id="which-mailboxes-count" tabindex="-1">Which mailboxes count <a class="header-anchor" href="#which-mailboxes-count" aria-label="Permalink to &quot;Which mailboxes count&quot;">​</a></h2><p>A mailbox counts as a seat when it holds archived emails and belongs to a person. Each mailbox is classified by the first rule below that applies:</p><table tabindex="0"><thead><tr><th>Order</th><th>Rule</th><th>Result</th></tr></thead><tbody><tr><td>1</td><td>The address is a placeholder created by journaling when the owner of an email could not be determined.</td><td>Not a seat</td></tr><tr><td>2</td><td>An administrator has marked the mailbox as a person.</td><td>Seat</td></tr><tr><td>3</td><td>The part of the address before <code>@</code> is a role name (see below).</td><td>Not a seat</td></tr><tr><td>4</td><td>Microsoft 365 reports the mailbox as shared, a room or equipment.</td><td>Not a seat</td></tr><tr><td>5</td><td>An administrator has marked the mailbox as shared.</td><td>Not a seat</td></tr><tr><td>6</td><td>None of the above.</td><td>Seat</td></tr></tbody></table><p>Mailboxes that hold no archived emails are never counted, even if your directory lists them.</p><h3 id="role-names" tabindex="-1">Role names <a class="header-anchor" href="#role-names" aria-label="Permalink to &quot;Role names&quot;">​</a></h3><p>A mailbox is treated as a role mailbox when the part of its address before <code>@</code> exactly matches one of these names:</p><p><code>postmaster</code>, <code>hostmaster</code>, <code>webmaster</code>, <code>abuse</code>, <code>noc</code>, <code>security</code>, <code>usenet</code>, <code>news</code>, <code>uucp</code>, <code>ftp</code>, <code>sales</code>, <code>marketing</code>, <code>support</code>, <code>info</code>, <code>contact</code>, <code>noreply</code>, <code>no-reply</code>, <code>no_reply</code>, <code>donotreply</code>, <code>do-not-reply</code>, <code>admin</code>, <code>billing</code>, <code>hr</code>, <code>jobs</code>, <code>careers</code>, <code>newsletter</code>, <code>notifications</code>, <code>alerts</code>, <code>helpdesk</code>, <code>service</code>, <code>office</code>, <code>hello</code>, <code>mailer-daemon</code>, <code>team</code></p><p>The list is based on RFC 2142 and common practice. Only exact matches count: <code>support@example.com</code> is a role mailbox, <code>support2@example.com</code> is not.</p><p>Administrators can add names to this list on the Seats page. The built-in names cannot be removed. If a person uses one of these addresses, mark that mailbox as a person.</p><h3 id="microsoft-365" tabindex="-1">Microsoft 365 <a class="header-anchor" href="#microsoft-365" aria-label="Permalink to &quot;Microsoft 365&quot;">​</a></h3><p>Open Archiver reads the mailbox type from Microsoft 365 when the <strong>MailboxSettings.Read</strong> application permission is granted. Shared mailboxes, rooms and equipment are then recognized automatically.</p><p>Without this permission, Open Archiver uses the license state instead. An account that has no license but still has a mailbox is treated as a shared mailbox, because that is how Exchange stores shared mailboxes. An account with a license is treated as a person.</p><h3 id="google-workspace-imap-and-imported-files" tabindex="-1">Google Workspace, IMAP and imported files <a class="header-anchor" href="#google-workspace-imap-and-imported-files" aria-label="Permalink to &quot;Google Workspace, IMAP and imported files&quot;">​</a></h3><p>These sources do not report whether a mailbox is shared. Role names apply as usual, and an administrator can mark any other mailbox as shared.</p><h2 id="counting-several-addresses-as-one-person" tabindex="-1">Counting several addresses as one person <a class="header-anchor" href="#counting-several-addresses-as-one-person" aria-label="Permalink to &quot;Counting several addresses as one person&quot;">​</a></h2><p>Open Archiver counts the following as a single seat:</p><ul><li><strong>Aliases from your directory.</strong> Microsoft 365 proxy addresses and Google Workspace aliases are read automatically.</li><li><strong>Organization domains.</strong> On the Seats page, add a domain group with a primary domain and at least one alias domain. <code>john@example.com</code> and <code>john@example.org</code> then count as one seat. Domains configured on journaling sources are included automatically.</li><li><strong>Manual links.</strong> An administrator can link two mailboxes that belong to the same person, for example a PST import and the person&#39;s live mailbox.</li></ul><h2 id="restrictions" tabindex="-1">Restrictions <a class="header-anchor" href="#restrictions" aria-label="Permalink to &quot;Restrictions&quot;">​</a></h2><p>The following changes are not allowed, so that the seat count can be verified:</p><ul><li>A mailbox that Microsoft 365 has classified, or that belongs to a licensed Microsoft 365 account, cannot be marked as shared. Change the mailbox in Microsoft 365 instead.</li><li>Two separate accounts from the same directory cannot be combined into one seat, through domain groups or manual links.</li><li>Built-in role names cannot be removed.</li></ul><p>Every change an administrator makes on the Seats page is recorded in the audit log, with the user who made it.</p><h2 id="information-sent-to-the-license-server" tabindex="-1">Information sent to the license server <a class="header-anchor" href="#information-sent-to-the-license-server" aria-label="Permalink to &quot;Information sent to the license server&quot;">​</a></h2><p>Enterprise deployments contact the license server once a day, and when the application starts. The request contains:</p><ul><li>the license identifier, a deployment identifier and the software version</li><li>the number of seats</li><li>counts that explain the number of seats, such as how many mailboxes were excluded by each rule and how many addresses were combined</li><li>a one-way hash of each role name an administrator added, for example <code>frontdesk</code></li></ul><p><strong>No email addresses are sent, in plain text or hashed.</strong> No names, emails or attachments are sent either. The list of mailboxes that administrators have marked stays on your deployment, in the Seats page and the audit log.</p><p>If the license server considers the number of manual exclusions unusual, a warning appears on the <strong>License Status</strong> page. No features are disabled because of this warning.</p><h2 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently asked questions&quot;">​</a></h2><p><strong>Do we still pay for someone who has left?</strong> Yes, as long as their emails are kept in the archive. Removing their account from your directory does not delete the archived emails. The seat is released when the emails are deleted, for example by a retention policy. Mailboxes that your directory has not listed for 30 days are shown on the Seats page.</p><p>On Microsoft 365, if you remove a person&#39;s license before you delete their account, the mailbox looks like a shared mailbox for a short time. Once Microsoft 365 has not listed the account for 30 days, it counts as a seat again.</p><p><strong>Is each imported PST file a seat?</strong> Yes, unless you link it to another mailbox. If the person also has a live mailbox in the archive, link the two and they count as one seat.</p><p><strong>Google charges us for <code>contact@</code>. Does Open Archiver?</strong> No. <code>contact</code> is a role name, so the mailbox is not counted.</p><p><strong>We run several application servers. Are seats counted per server?</strong> No. All servers that share one database are one deployment with one seat count.</p><h2 id="the-seats-page" tabindex="-1">The Seats page <a class="header-anchor" href="#the-seats-page" aria-label="Permalink to &quot;The Seats page&quot;">​</a></h2><p>Go to <strong>Dashboard → Admin → Seats</strong> to see:</p><ul><li>the number of seats and the number of archived mailboxes</li><li>the breakdown of excluded and combined mailboxes</li><li>every mailbox, with the rule that decided whether it counts</li><li>the organization domains and additional role names</li></ul><p>The seat count is recalculated before each daily license check. When you open the Seats page and the figures are more than 10 minutes old, the page shows the previous figures and recalculates in the background; reload the page to see the result. Click <strong>Recount</strong> to recalculate immediately.</p>',42)]))}const u=a(n,[["render",r]]);export{p as __pageData,u as default};
